	const [c, ctx] = makeCanvas(size, size);
	const rand = seededRand(kind === "pine" ? 1919 : 2020);
	ctx.clearRect(0, 0, size, size);
	if (kind === "pine") {
		ctx.strokeStyle = "rgb(88,66,44)";
		ctx.lineWidth = 7;
		ctx.beginPath();
		ctx.moveTo(size * .5, size * .96);
		ctx.lineTo(size * .5, size * .1);
		ctx.stroke();
		const subBranches = 16;
		for (let b = 0; b < subBranches; b++) {
			const t = b / subBranches;
			const y = size * (.9 - t * .78);
			const span = size * (.44 - t * .34);
			for (const side of [-1, 1]) {
				const ex = size * .5 + side * span;
				const ey = y - size * (.08 + rand() * .06);
				ctx.strokeStyle = "rgb(44,68,36)";
				ctx.lineWidth = 4;
				ctx.beginPath();
				ctx.moveTo(size * .5, y);
				ctx.lineTo(ex, ey);
				ctx.stroke();
				const needles = 34;
				for (let n = 0; n < needles; n++) {
					const nt = n / needles;
					const bx = MathUtils.lerp(size * .5, ex, nt);
					const by = MathUtils.lerp(y, ey, nt);
					const nAng = side * .7 + (rand() - .5) * 1.1 - Math.PI * .5;
					const nLen = 12 + rand() * 14;
					const g = clampByte(72 + rand() * 48);
					ctx.strokeStyle = `rgb(${clampByte(36 + rand() * 28)},${g},${clampByte(28 + rand() * 20)})`;
					ctx.lineWidth = 2.6;
					ctx.beginPath();
					ctx.moveTo(bx, by);
					ctx.lineTo(bx + Math.cos(nAng) * nLen, by + Math.sin(nAng) * nLen);
					ctx.stroke();
				}
			}
		}
	} else {
		ctx.strokeStyle = "rgb(112,118,58)";
		ctx.lineWidth = 6;
		ctx.beginPath();
		ctx.moveTo(size * .5, size * .98);
		ctx.lineTo(size * .5, size * .06);
		ctx.stroke();
		const pairs = 22;
		for (let i = 0; i < pairs; i++) {
			const t = i / pairs;
			const y = size * (.9 - t * .82);
			const len = size * (.44 * Math.sin(Math.PI * (.14 + t * .8)));
			for (const side of [-1, 1]) {
				const g = clampByte(96 + rand() * 44);
				ctx.fillStyle = `rgb(${clampByte(74 + rand() * 32)},${g},${clampByte(38 + rand() * 22)})`;
				ctx.beginPath();
				ctx.moveTo(size * .5, y);
				ctx.quadraticCurveTo(size * .5 + side * len * .6, y - 10, size * .5 + side * len, y + 6);
				ctx.quadraticCurveTo(size * .5 + side * len * .5, y + 4, size * .5, y + 5);
				ctx.closePath();
				ctx.fill();
			}
		}
	}
