		color,
		roughness,
		metalness,
		flatShading: false,
		...texSet ? {
			bumpMap: texSet.bumpMap,
			bumpScale: metalness >= .45 ? .0025 : .003,
			roughnessMap: texSet.roughnessMap
		} : {},
		...extra
