function makeExtruded(pts, thickness, bevel = .0025) {
	const s = new Shape();
	s.moveTo(pts[0][0], pts[0][1]);
	for (let i = 1; i < pts.length; i++) s.lineTo(pts[i][0], pts[i][1]);
	s.closePath();
	const g = new ExtrudeGeometry(s, {
		depth: thickness,
		bevelEnabled: bevel > 0,
		bevelThickness: bevel,
		bevelSize: bevel,
		bevelSegments: 2
	});
	g.translate(0, 0, -thickness / 2);
	g.rotateY(-Math.PI / 2);
	g.computeVertexNormals();
	return g;
}
function makeLathe(profile, segs = 14) {
	const g = new LatheGeometry(profile.map(([r, y]) => new Vector2(r, y)), segs);
	g.rotateX(-Math.PI / 2);
	g.computeVertexNormals();
	return g;
}
