/**
* Visible 3D billowing parachute canopy & suspension risers for aerial bailout.
*/
function createParachuteCanopy() {
	const group = new Group();
	const canopyMat = makePbrMat(7241309, .86, .03, false, {
		side: 2,
		...pbrSetProps(typeof document !== "undefined" ? getBduCamoPbrSet("allies") : null, .008)
	});
	const trimMat = makePbrMat(14077368, .88, .02, false, { side: 2 });
	const cordMat = makePbrMat(2040865, .7, .1);
	const dome = new Mesh(new SphereGeometry(3.1, 24, 12, 0, Math.PI * 2, 0, Math.PI * .48), canopyMat);
	dome.position.y = 3.4;
	dome.scale.set(1, .68, 1);
	const skirtRing = new Mesh(new TorusGeometry(3.04, .08, 8, 24), trimMat);
	skirtRing.rotation.x = Math.PI / 2;
	skirtRing.position.y = 3.55;
	group.add(dome, skirtRing);
	for (let i = 0; i < 8; i++) {
		const ang = i * Math.PI * 2 / 8;
		const tx = Math.cos(ang) * 2.95;
		const tz = Math.sin(ang) * 2.95;
		const cord = new Mesh(new TubeGeometry(new LineCurve3(new Vector3(tx * .25, .35, tz * .25), new Vector3(tx, 3.55, tz)), 4, .014, 4, false), cordMat);
		group.add(cord);
	}
	return group;
}
