	ensureEngineNodes(ctx) {
		if (this.engineNodesReady || !this.noiseBuffer) return;
		this.engineNodesReady = true;
		const now = ctx.currentTime;
		const osc1 = ctx.createOscillator();
		osc1.type = "sawtooth";
		osc1.frequency.setValueAtTime(60, now);
		const osc2 = ctx.createOscillator();
		osc2.type = "triangle";
		osc2.frequency.setValueAtTime(30, now);
		const lp = ctx.createBiquadFilter();
		lp.type = "lowpass";
		lp.frequency.setValueAtTime(220, now);
		lp.Q.value = .65;
		const eg = ctx.createGain();
		eg.gain.setValueAtTime(0, now);
		osc1.connect(lp);
		osc2.connect(lp);
		lp.connect(eg);
		eg.connect(ctx.destination);
		osc1.start(now);
		osc2.start(now);
		const wind = ctx.createBufferSource();
		wind.buffer = this.noiseBuffer;
		wind.loop = true;
		const wFilter = ctx.createBiquadFilter();
		wFilter.type = "bandpass";
		wFilter.frequency.setValueAtTime(360, now);
		wFilter.Q.value = .7;
		const wg = ctx.createGain();
		wg.gain.setValueAtTime(0, now);
		wind.connect(wFilter);
		wFilter.connect(wg);
		wg.connect(ctx.destination);
		wind.start(now);
		this.engineOsc1 = osc1;
		this.engineOsc2 = osc2;
		this.engineFilter = lp;
		this.engineGain = eg;
		this.engineWindSrc = wind;
		this.engineWindFilter = wFilter;
		this.engineWindGain = wg;
	}
	stopEngineCue() {
		if (!this.ctx || !this.engineNodesReady) return;
		const now = this.ctx.currentTime;
		this.engineGain?.gain.setTargetAtTime(0, now, .06);
		this.engineWindGain?.gain.setTargetAtTime(0, now, .06);
	}
	playEngineCue(kind, intensity = .5, muffled = false) {
		const nowMs = performance.now();
		if (nowMs - this.lastEngineCueMs < 40) return;
		this.lastEngineCueMs = nowMs;
		const ctx = this.ensureContext();
		if (!ctx) return;
		this.ensureEngineNodes(ctx);
		if (!this.engineNodesReady) return;
		const load01 = Math.max(0, Math.min(1, intensity));
		const cabinAtten = muffled ? .62 : 1;
		const cabinCutoff = muffled ? .68 : 1;
		const now = ctx.currentTime;
		if (kind === "heli") {
			const f1 = 18 + load01 * 14;
			const f2 = 112 + load01 * 56;
			this.engineOsc1?.frequency.setTargetAtTime(f1, now, .08);
			this.engineOsc2?.frequency.setTargetAtTime(f2, now, .08);
			this.engineFilter?.frequency.setTargetAtTime((240 + load01 * 180) * cabinCutoff, now, .08);
			this.engineGain?.gain.setTargetAtTime((.036 + load01 * .04) * cabinAtten, now, .08);
			this.engineWindFilter?.frequency.setTargetAtTime(210 + load01 * 240, now, .08);
			this.engineWindGain?.gain.setTargetAtTime((.02 + load01 * .032) * cabinAtten, now, .08);
		} else if (kind === "air") {
			const f1 = 74 + load01 * 52;
			const f2 = f1 * .505;
			this.engineOsc1?.frequency.setTargetAtTime(f1, now, .08);
			this.engineOsc2?.frequency.setTargetAtTime(f2, now, .08);
			this.engineFilter?.frequency.setTargetAtTime((220 + load01 * 170) * cabinCutoff, now, .08);
			this.engineGain?.gain.setTargetAtTime((.032 + load01 * .036) * cabinAtten, now, .08);
			this.engineWindFilter?.frequency.setTargetAtTime(320 + load01 * 320, now, .08);
			this.engineWindGain?.gain.setTargetAtTime((.015 + load01 * .038) * cabinAtten, now, .08);
		} else {
			const f1 = 36 + load01 * 30;
			const f2 = f1 * 1.49;
			this.engineOsc1?.frequency.setTargetAtTime(f1, now, .08);
			this.engineOsc2?.frequency.setTargetAtTime(f2, now, .08);
			this.engineFilter?.frequency.setTargetAtTime((125 + load01 * 90) * cabinCutoff, now, .08);
			this.engineGain?.gain.setTargetAtTime((.025 + load01 * .035) * cabinAtten, now, .08);
			this.engineWindGain?.gain.setTargetAtTime(0, now, .08);
		}
	}
