			const osc = ctx.createOscillator();
			osc.type = "square";
			osc.frequency.setValueAtTime(idx === 2 ? 640 : 320 + idx * 95, now + offset);
			osc.frequency.exponentialRampToValueAtTime(125, now + offset + .045);
			const g = ctx.createGain();
			g.gain.setValueAtTime(.085, now + offset);
			g.gain.exponentialRampToValueAtTime(.001, now + offset + .05);
			osc.connect(g);
