	const hood = new Mesh(new BoxGeometry(2.35, 1.02, 1.85), bodyMat);
	hood.position.set(0, 1.45, 2.78);
	hood.castShadow = true;
	const cab = new Mesh(new BoxGeometry(2.42, 1.56, 1.55), bodyMat);
	cab.position.set(0, 1.72, 1.25);
	cab.castShadow = true;
	const windshield = new Mesh(new BoxGeometry(2.14, .62, .08), glassMat);
	windshield.position.set(0, 2.02, 2.04);
	const grille = new Mesh(new BoxGeometry(1.88, .68, .1), darkMat);
	grille.position.set(0, 1.4, 3.72);
	root.add(hood, cab, windshield, grille);
