	bedFloor.position.set(0, 1.05, -1.78);
	bedFloor.receiveShadow = true;
	root.add(bedFloor);
	for (const sx of [-1.2, 1.2]) {
		const sideWall = new Mesh(new BoxGeometry(.1, .98, 4.75), bodyMat);
		sideWall.position.set(sx, 1.62, -1.78);
		sideWall.castShadow = true;
		const bench = new Mesh(new BoxGeometry(.46, .1, 4.3), woodMat);
		bench.position.set(sx * .72, 1.45, -1.75);
		root.add(sideWall, bench);
	}
