	frontBulkhead.position.set(0, 1.7, .54);
	const tailgate = new Mesh(new BoxGeometry(2.44, .65, .1), bodyMat);
	tailgate.position.set(0, 1.42, -4.12);
	root.add(frontBulkhead, tailgate);
	for (const rz of [
		.1,
		-1.35,
		-2.8,
		-3.95
	]) {
		const hoop = new Mesh(new TorusGeometry(1.18, .045, 6, 12, Math.PI), darkMat);
		hoop.position.set(0, 2.1, rz);
		root.add(hoop);
	}
	const frontTarp = new Mesh(new CylinderGeometry(1.2, 1.2, 1.45, 10, 1, true, -Math.PI * .5, Math.PI), canvasMat);
	frontTarp.rotation.x = Math.PI / 2;
