		if (spec.mode === "letter_intro" || spec.mode === "base_walk" || spec.mode === "blast_alarm") shouldComplete = this.campaignObjectiveDone && this.campaignElapsed >= minDialogWait || this.campaignElapsed >= spec.durationHintSec;
		else if (spec.mode === "training_range") shouldComplete = (this.campaignSet?.targets.filter((t) => t.hit).length ?? 0) >= spec.targetKills;
		else if (spec.mode === "night_parachute") shouldComplete = !this.isParachuting && (this.campaignObjectiveDone || this.campaignElapsed >= minDialogWait);
